select count(0) > 0 from mes_contract_project_bolt_sleeve_link mcpbsl

    mcpbsl.bool_delete_enum = false
    
        and mcpbsl.id <> #{id}
    
    
        and
        
            find_in_set(#{i}, mcpbsl.type) > 0
        
    
    
        and mcpbsl.contract_project_id = #{contractProjectId}

SELECT
mcpbsl.*,
mbp.name AS process_name
FROM mes_contract_project_bolt_sleeve_link mcpbsl
LEFT JOIN mes_building_process mbp ON mbp.product_type = 2 AND mbp.id = mcpbsl.process_id
WHERE mcpbsl.bool_delete_enum = FALSE

    AND mcpbsl.contract_project_id in (
    
        #{i}
    
    )


    AND mcpbsl.process_id = #{processId}

SELECT mcpbsl.*, mbp.name AS process_name FROM mes_contract_project_bolt_sleeve_link mcpbsl LEFT JOIN mes_building_process mbp ON mbp.product_type = 2 AND mbp.id = mcpbsl.process_id WHERE mcpbsl.bool_delete_enum = FALSE
AND mcpbsl.contract_project_id = #{projectId}
AND FIND_IN_SET(#{typeName}, mcpbsl.type) > 0
